AQ,QAAA,CAAS,OAAO,EAE9B,MAAMA,CAAAA,CAAQ,YAAA,EAAa,CAE3B,MAAMJ,CAAAA,CAAWrF,CAAAA,CAAQ,cAAc,EACzC,CAAC,CAAA,CAEH6E,CAAAA,CACG,OAAA,CAAQ,SAAA,CAAW,6DAA6D,CAAA,CAChF,MAAA,CAAO,eAAA,CAAiB,oCAAqC,CAAE,OAAA,CAAS,IAAK,CAAC,EAC9E,MAAA,CAAO,MAAOa,CAAAA,EAAY,CACzB,IAAM1F,CAAAA,CAAS,MAAM+E,CAAAA,EAAc,CAEnC,MADgB,IAAIxC,CAAAA,CAAQvC,CAAM,EACpB,OAAA,CAAQ0F,CAAAA,CAAQ,IAAI,EACpC,CAAC,CAAA,CAEHb,CAAAA,CAAI,IAAA,EAAK,CACTA,EAAI,KAAA,EAAM","file":"index.cjs","sourcesContent":["import fs from 'fs-extra';\nimport path from 'path';\nimport glob from 'fast-glob';\nimport { pathToFileURL } from 'url';\nimport { LanderConfig } from '@/types/config';\n\nexport class WorkspaceGenerator {\n  private config: LanderConfig;\n  private workspaceDir: string;\n\n  constructor(config: LanderConfig) {\n    this.config = config;\n    this.workspaceDir = path.resolve(config.projectRoot, '.lander-engine');\n  }\n\n  /**\n   * Initializes the hidden workspace.\n   */\n  async generate() {\n    await fs.ensureDir(this.workspaceDir);\n\n    // 1. Copy/Link Astro Base Template\n    const templateDir = path.resolve(this.config.engineRoot, 'templates/astro-base');\n\n    if (await fs.pathExists(templateDir)) {\n      // Clean target directory first to avoid stale files\n      await fs.emptyDir(this.workspaceDir);\n      \n      try {\n        await fs.copy(templateDir, this.workspaceDir, {\n          overwrite: true,\n          dereference: true,\n        });\n\n        // Resolve absolute paths for integrations to ensure Astro can find them even if not hoisted\n        const compressorPath = this.resolvePackage('astro-compressor');\n\n        const configPath = path.join(this.workspaceDir, 'astro.config.mjs');\n        let configContent = await fs.readFile(configPath, 'utf8');\n        configContent = configContent.replace('{{ASTRO_COMPRESSOR_PATH}}', compressorPath);\n        \n        await fs.writeFile(configPath, configContent);\n\n      } catch (copyErr) {\n        console.error('Failed to copy Astro template:', copyErr);\n        throw new Error(`Failed to initialize workspace: ${copyErr instanceof Error ? copyErr.message : String(copyErr)}`);\n      }\n    } else {\n      throw new Error(`Lander Engine template not found at ${templateDir}. This usually means the lander-engine package installation is incomplete or corrupted.`);\n    }\n\n    // 2. Copy User Assets Directory\n    await this.copyAssets();\n\n    // 3. Generate Registry Manifest\n    await this.generateRegistryManifest();\n\n    // 4. Generate domain routing entry point (if routing.config.js is present)\n    await this.generateDomainRouting();\n\n    // 4. Generate lander config json for global error pages\n    await this.generateConfigJson();\n  }\n\n  /**\n   * Copies the user's configured assets directory to the workspace.\n   */\n  private async copyAssets() {\n    const assetsDir = path.resolve(this.config.projectRoot, this.config.assetsDir || 'assets');\n    const targetAssetsDir = path.join(this.workspaceDir, 'src/assets');\n\n    if (await fs.pathExists(assetsDir)) {\n      try {\n        await fs.copy(assetsDir, targetAssetsDir, {\n          overwrite: true,\n          dereference: true,\n        });\n      } catch (copyErr) {\n        console.error('Failed to copy assets directory:', copyErr);\n      }\n    } else {\n      // Ensure the target directory exists even if the user has no assets\n      await fs.ensureDir(targetAssetsDir);\n    }\n  }\n\n  /**\n   * Resolves a package path relative to the engine root as a file URL.\n   */\n  private resolvePackage(packageName: string): string {\n    try {\n      // Try to find it in the engine's node_modules\n      const packagePath = path.join(this.config.engineRoot, 'node_modules', packageName);\n      if (fs.existsSync(packagePath)) {\n        return pathToFileURL(packagePath).toString();\n      }\n      // Fallback to plain name if not found (might be hoisted in user project)\n      return packageName;\n    } catch {\n      return packageName;\n    }\n  }\n\n  /**\n   * Scans user directories and generates a manifest for the runtime registry.\n   */\n  private async generateRegistryManifest() {\n    const componentsDir = path.resolve(this.config.projectRoot, this.config.componentsDir || 'components');\n    const actionsDir = path.resolve(this.config.projectRoot, this.config.actionsDir || 'actions');\n\n    const componentFiles = await glob('**/*.{tsx,jsx,astro,vue,svelte}', { cwd: componentsDir });\n    const actionFiles = await glob('**/*.{ts,js}', { cwd: actionsDir });\n\n    // 1. Generate core registry manifest (for actions and general registry)\n    let manifestContent = `// Auto-generated manifest\\n`;\n    manifestContent += `import { registry } from 'lander-engine/core';\\n\\n`;\n\n    // 2. Generate Registry.astro for static component mapping (Astro needs static imports for Islands)\n    let astroRegistryContent = `---\n// Auto-generated Astro Registry\\n`;\n\n    let componentIndex = 0;\n    \n    // Import all components\n    componentFiles.forEach((file) => {\n      const name = path.basename(file, path.extname(file));\n      const importPath = path.resolve(componentsDir, file).replace(/\\\\/g, '/');\n      astroRegistryContent += `import Component_${componentIndex} from '${importPath}';\\n`;\n      manifestContent += `import Component_${componentIndex} from '${importPath}';\\n`;\n      manifestContent += `registry.registerComponent('${name}', Component_${componentIndex});\\n`;\n      componentIndex++;\n    });\n\n    actionFiles.forEach((file, index) => {\n      const name = path.basename(file, path.extname(file));\n      const importPath = path.resolve(actionsDir, file).replace(/\\\\/g, '/');\n      manifestContent += `import * as Action_${index} from '${importPath}';\\n`;\n      manifestContent += `registry.registerActions(Action_${index});\\n`;\n    });\n\n    astroRegistryContent += `\nconst { component, props } = Astro.props;\n---\n`;\n\n    componentIndex = 0;\n    componentFiles.forEach((file) => {\n      const name = path.basename(file, path.extname(file));\n      const isAstroComponent = file.endsWith('.astro');\n      \n      if (isAstroComponent) {\n        // Astro components don't need client: directive\n        astroRegistryContent += `{component === '${name}' && <Component_${componentIndex} {...props} />}\\n`;\n      } else {\n        // React/Vue/Svelte components get client:load\n        astroRegistryContent += `{component === '${name}' && <Component_${componentIndex} {...props} client:load />}\\n`;\n      }\n      componentIndex++;\n    });\n\n    const manifestPath = path.join(this.workspaceDir, 'src/registry-manifest.ts');\n    const astroRegistryPath = path.join(this.workspaceDir, 'src/Registry.astro');\n    \n    await fs.ensureDir(path.dirname(manifestPath));\n    await fs.writeFile(manifestPath, manifestContent);\n    await fs.writeFile(astroRegistryPath, astroRegistryContent);\n  }\n\n  /**\n   * Generates domain-to-campaign routing artifacts from routing.config.js.\n   *\n   * Produces three outputs:\n   *  - src/pages/index.astro  — universal client-side domain redirect (works on any static host)\n   *  - public/_redirects      — Netlify host-based redirect rules\n   *  - public/vercel.json     — Vercel host-based redirect rules\n   */\n  private async generateDomainRouting() {\n    const routingConfig = this.config.routingConfig;\n    if (!routingConfig || Object.keys(routingConfig).length === 0) return;\n\n    const jsonConfigsDir = path.resolve(\n      this.config.projectRoot,\n      this.config.jsonConfigsDir || 'json_configs'\n    );\n\n    // Resolve domain → full path by reading each campaign's initialStep from flow.json\n    const domainPaths: Record<string, string> = {};\n    for (const [domain, campaignId] of Object.entries(routingConfig)) {\n      try {\n        const flow = await fs.readJson(path.join(jsonConfigsDir, campaignId, 'flow.json'));\n        const initialStep = flow.initialStep || 'main';\n        domainPaths[domain] = `/${campaignId}/${initialStep}`;\n      } catch {\n        console.warn(\n          `routing.config.js: could not read flow.json for campaign \"${campaignId}\" (domain: ${domain}), falling back to /${campaignId}`\n        );\n        domainPaths[domain] = `/${campaignId}`;\n      }\n    }\n\n    // --- 1. src/pages/index.astro (universal — works on any static host) ---\n    const domainMapJson = JSON.stringify(domainPaths, null, 2);\n    const indexAstro = `---\n// Auto-generated by lander-engine — domain routing entry point\n// Redirects each domain to its configured campaign's initial step.\n---\n<html>\n  <head>\n    <meta charset=\"utf-8\" />\n    <title>Redirecting...</title>\n  </head>\n  <body>\n    <script>\n      (function () {\n        var domainMap = ${domainMapJson};\n        var host = window.location.hostname;\n        var target = domainMap[host];\n        if (target) {\n          window.location.replace(target + window.location.search);\n        }\n      })();\n    </script>\n    <noscript>Please enable JavaScript to use this site.</noscript>\n  </body>\n</html>\n`;\n\n    // --- 2. public/_redirects (Netlify) ---\n    let netlifyRedirects = `# Lander Engine — domain routing (auto-generated)\\n`;\n    for (const [domain, targetPath] of Object.entries(domainPaths)) {\n      netlifyRedirects += `/  ${targetPath}  302!  Host=${domain}\\n`;\n    }\n\n    // --- 3. public/vercel.json (Vercel) ---\n    const vercelRedirects = Object.entries(domainPaths).map(([domain, targetPath]) => ({\n      source: '/',\n      destination: targetPath,\n      has: [{ type: 'host', value: domain }],\n      permanent: false,\n    }));\n    const vercelJson = JSON.stringify({ redirects: vercelRedirects }, null, 2);\n\n    await fs.ensureDir(path.join(this.workspaceDir, 'src/pages'));\n    await fs.ensureDir(path.join(this.workspaceDir, 'public'));\n\n    await fs.writeFile(path.join(this.workspaceDir, 'src/pages/index.astro'), indexAstro);\n    await fs.writeFile(path.join(this.workspaceDir, 'public/_redirects'), netlifyRedirects);\n    await fs.writeFile(path.join(this.workspaceDir, 'public/vercel.json'), vercelJson);\n\n    console.log(`Domain routing configured for ${Object.keys(domainPaths).length} domain(s).`);\n  }\n\n  /**\n   * Generates a config.json inside the workspace for templates to read global config.\n   */\n  private async generateConfigJson() {\n    const configPath = path.join(this.workspaceDir, 'src/lander-config.json');\n    const { errorPages } = this.config;\n    await fs.ensureDir(path.dirname(configPath));\n    await fs.writeJson(configPath, { errorPages: errorPages || {} }, { spaces: 2 });\n  }\n}\n","import { spawn } from 'child_process';\nimport path from 'path';\nimport { LanderConfig } from '@/types/config';\n\nexport class Builder {\n  private config: LanderConfig;\n  private workspaceDir: string;\n\n  constructor(config: LanderConfig) {\n    this.config = config;\n    this.workspaceDir = path.resolve(config.projectRoot, '.lander-engine');\n  }\n\n  /**\n   * Invokes an Astro CLI command within the hidden workspace context.\n   */\n  async runAstro(command: 'dev' | 'build') {\n    return new Promise<void>((resolve, reject) => {\n      const astroBin = path.resolve(this.config.projectRoot, 'node_modules/.bin/astro');\n      \n      // Make the config loader run against the real project source, not the hidden workspace copy.\n      const jsonConfigsDir = this.config.jsonConfigsDir\n        ? path.resolve(this.config.projectRoot, this.config.jsonConfigsDir)\n        : path.resolve(this.config.projectRoot, 'json_configs');\n\n      const child = spawn(astroBin, [command], {\n        cwd: this.workspaceDir,\n        stdio: 'inherit',\n        shell: false,\n        env: {\n          ...process.env,\n          LANDER_JSON_CONFIGS_DIR: jsonConfigsDir,\n        },\n      });\n\n      child.on('close', (code) => {\n        if (code === 0) {\n          resolve();\n        } else {\n          reject(new Error(`Astro ${command} failed with exit code ${code}`));\n        }\n      });\n    });\n  }\n\n  async logPageSizes() {\n    const distDir = path.resolve(this.workspaceDir, 'dist');\n    const fs = await import('fs/promises');\n    const pathLib = await import('path');\n\n    async function walk(dir: string): Promise<string[]> {\n      const entries = await fs.readdir(dir, { withFileTypes: true });\n      const files: string[] = [];\n      for (const entry of entries) {\n        const fullPath = pathLib.join(dir, entry.name);\n        if (entry.isDirectory()) {\n          files.push(...(await walk(fullPath)));\n        } else {\n          files.push(fullPath);\n        }\n      }\n      return files;\n    }\n\n    try {\n      const allFiles = await walk(distDir);\n      const htmlFiles = allFiles.filter((f) => f.endsWith('.html'));\n      \n      if (htmlFiles.length === 0) {\n        console.log('No generated HTML pages found to report sizes.');\n        return;\n      }\n\n      console.log('\\nGenerated page sizes:');\n      let totalRaw = 0;\n      let totalGzip = 0;\n      let totalBrotli = 0;\n\n      for (const file of htmlFiles) {\n        const stats = await fs.stat(file);\n        const rawSize = stats.size;\n        totalRaw += rawSize;\n\n        const relativePath = pathLib.relative(distDir, file).replace(/\\\\/g, '/');\n        \n        // Check for compressed versions\n        let gzipSize: number | null = null;\n        let brotliSize: number | null = null;\n\n        try {\n          const gzStats = await fs.stat(file + '.gz');\n          gzipSize = gzStats.size;\n          totalGzip += gzipSize;\n        } catch {}\n\n        try {\n          const brStats = await fs.stat(file + '.br');\n          brotliSize = brStats.size;\n          totalBrotli += brotliSize;\n        } catch {}\n\n        const rawKb = (rawSize / 1024).toFixed(2);\n        let info = ` - /${relativePath} (${rawKb} KB)`;\n        \n        if (brotliSize) {\n          const brKb = (brotliSize / 1024).toFixed(2);\n          const ratio = ((1 - brotliSize / rawSize) * 100).toFixed(0);\n          info += ` → Brotli: ${brKb} KB (-${ratio}%)`;\n        } else if (gzipSize) {\n          const gzKb = (gzipSize / 1024).toFixed(2);\n          const ratio = ((1 - gzipSize / rawSize) * 100).toFixed(0);\n          info += ` → Gzip: ${gzKb} KB (-${ratio}%)`;\n        }\n\n        console.log(info);\n      }\n\n      console.log('---');\n      console.log(`Total HTML Raw:    ${(totalRaw / 1024).toFixed(2)} KB`);\n      if (totalBrotli > 0) {\n        console.log(`Total HTML Brotli: ${(totalBrotli / 1024).toFixed(2)} KB (-${((1 - totalBrotli / totalRaw) * 100).toFixed(0)}%)`);\n      } else if (totalGzip > 0) {\n        console.log(`Total HTML Gzip:   ${(totalGzip / 1024).toFixed(2)} KB (-${((1 - totalGzip / totalRaw) * 100).toFixed(0)}%)`);\n      }\n      console.log('');\n    } catch (err) {\n      console.warn('Could not compute page sizes:', err);\n    }\n  }\n\n  /**\n   * Starts a preview server for the built project with compression support.\n   */\n  async preview(port: number = 4321) {\n    const distDir = path.resolve(this.workspaceDir, 'dist');\n    const fs = await import('fs');\n\n    if (!fs.existsSync(distDir)) {\n      throw new Error(`Build directory not found at ${distDir}. Run 'lander build' first.`);\n    }\n\n    // Dynamic import to avoid CJS/ESM issues with sirv if necessary, but sirv is standard\n    const sirv = (await import('sirv')).default;\n    const http = await import('http');\n\n    const server = sirv(distDir, {\n      dev: false,\n      gzip: true,\n      brotli: true,\n      single: false,\n      dotfiles: true,\n    });\n\n    http.createServer(server).listen(port, (err?: any) => {\n      if (err) throw err;\n      console.log(`\\n🚀 Preview server running at http://localhost:${port}`);\n      console.log(`Serving with Gzip and Brotli support from: ${distDir}\\n`);\n    });\n  }\n}\n\n","#!/usr/bin/env node\nimport { cac } from 'cac';\nimport path from 'path';\nimport fs from 'fs-extra';\nimport { WorkspaceGenerator } from './generate';\nimport { Builder } from './build';\nimport { LanderConfig, UserLanderConfig, RoutingConfig } from '@/types/config';\n\nimport { fileURLToPath } from 'url';\nimport { dirname } from 'path';\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nconst cli = cac('lander');\n\nasync function resolveConfig(): Promise<LanderConfig> {\n  const projectRoot = process.cwd();\n  // __dirname is dist/cli, so we go up twice to reach the package root\n  const engineRoot = path.resolve(__dirname, '../../');\n  \n  // Simplified loader: in production this would use jiti or similar for TS support\n  const configPath = path.resolve(projectRoot, 'lander.config.js'); \n  let userConfig: UserLanderConfig = {};\n\n  if (await fs.pathExists(configPath)) {\n    try {\n      const module = await import(configPath);\n      userConfig = module.default || module;\n    } catch (e) {\n      console.warn('Failed to load lander.config.js, using defaults');\n    }\n  }\n\n  // Load routing.config.js (domain → campaign mapping)\n  let routingConfig: RoutingConfig | undefined;\n  const routingConfigPath = path.resolve(projectRoot, 'routing.config.js');\n  if (await fs.pathExists(routingConfigPath)) {\n    try {\n      const module = await import(routingConfigPath);\n      routingConfig = module.default || module;\n    } catch (e) {\n      console.warn('Failed to load routing.config.js, domain routing will be skipped');\n    }\n  }\n\n  return {\n    projectRoot,\n    engineRoot,\n    jsonConfigsDir: 'json_configs',\n    componentsDir: 'components',\n    actionsDir: 'actions',\n    outputDir: 'dist',\n    plugins: [],\n    routingConfig,\n    ...userConfig,\n  } as LanderConfig;\n}\n\nasync function runPlugins(config: LanderConfig, hook: 'onBeforeBuild' | 'onAfterBuild') {\n  if (!config.plugins) return;\n  for (const plugin of config.plugins) {\n    if (plugin[hook]) {\n      console.log(`Running plugin hook: ${plugin.name}.${hook}`);\n      await plugin[hook]!(config);\n    }\n  }\n}\n\ncli\n  .command('dev', 'Start the development server')\n  .action(async () => {\n    const config = await resolveConfig();\n    const generator = new WorkspaceGenerator(config);\n    const builder = new Builder(config);\n\n    await runPlugins(config, 'onBeforeBuild');\n\n    console.log('Generating workspace...');\n    await generator.generate();\n\n    console.log('Starting dev server...');\n    await builder.runAstro('dev');\n  });\n\ncli\n  .command('build', 'Build the static landing pages')\n  .action(async () => {\n    const config = await resolveConfig();\n    const generator = new WorkspaceGenerator(config);\n    const builder = new Builder(config);\n\n    await runPlugins(config, 'onBeforeBuild');\n\n    console.log('Generating workspace...');\n    await generator.generate();\n\n    console.log('Building project...');\n    await builder.runAstro('build');\n\n    await builder.logPageSizes();\n\n    await runPlugins(config, 'onAfterBuild');\n  });\n\ncli\n  .command('preview', 'Serve the built production project with compression support')\n  .option('--port <port>', 'Port to run the preview server on', { default: 4321 })\n  .action(async (options) => {\n    const config = await resolveConfig();\n    const builder = new Builder(config);\n    await builder.preview(options.port);\n  });\n\ncli.help();\ncli.parse();\n"]}
